import math

def solve_quadratic(a, b, c):
    # Solve ax^2 + bx + c = 0 for positive rational x
    if a == 0:
        if b == 0:
            return set() # No solution or infinite if c=0, but d_i cannot all be zero
        p = -c / b
        if p > 0 and abs(p - round(p)) < 1e-9: # Check if rational and positive
            return {p}
        return set()

    delta = b**2 - 4 * a * c
    if delta < 0:
        return set()

    sqrt_delta = math.isqrt(delta)
    if sqrt_delta * sqrt_delta != delta:
        return set() # Not a perfect square, p is irrational

    solutions = set()

    # Solution 1
    numerator1 = -b + sqrt_delta
    denominator = 2 * a
    if numerator1 / denominator > 0:
        # Check if rational (since numerator and denominator are integers, it must be rational)
        p1 = numerator1 / denominator
        solutions.add(p1)

    # Solution 2 (if distinct)
    if sqrt_delta != 0:
        numerator2 = -b - sqrt_delta
        if numerator2 / denominator > 0:
            p2 = numerator2 / denominator
            solutions.add(p2)

    return solutions

d_range = [-2, -1, 0, 1, 2]
solutions = set()

# Iterate over all combinations (d1, d2, d3)
for d3 in d_range:
    for d2 in d_range:
        for d1 in d_range:
            if d1 == 0 and d2 == 0 and d3 == 0:
                continue

            # Check Case 1: d3 = 0 (Linear equation d2*p + d1 = 0)
            if d3 == 0:
                if d2 == 0:
                    continue # Only d1 != 0 left. d1 = 0 is ruled out. If d1 != 0, no solution for p.
                p = -d1 / d2
                if p > 0:
                    solutions.add(p)
                continue

            # Check Case 2: d3 != 0 (Quadratic equation d3*p^2 + d2*p + d1 = 0)
            p_solutions = solve_quadratic(d3, d2, d1)
            solutions.update(p_solutions)

# Convert sets to list and sort for clean output
sorted_solutions = sorted(list(solutions))

print("Solutions found:", sorted_solutions)
